def match_parens(lst):
    # Count the number of '(' and ')' in both strings
    total_open = lst[0].count('(') + lst[1].count('(')
    total_close = lst[0].count(')') + lst[1].count(')')

    # Check if the counts are equal
    if total_open != total_close:
        return 'No'

    # If counts are equal, check all possible concatenations
    for i in range(2):
        # Check if the current string can be balanced with the other string
        if is_balanced(lst[i] + lst[1 - i]):
            return 'Yes'

    return 'No'

def is_balanced(s):
    # Check if a string has balanced parentheses
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

# Test cases
