def do_algebra(operator, operand):
    # Start with the first operand
    result = operand[0]

    # Iterate over the operators and operands
    for i, op in enumerate(operator):
        if op == '+':
            result += operand[i + 1]
        elif op == '-':
            result -= operand[i + 1]
        elif op == '*':
            result *= operand[i + 1]
        elif op == '//':
            result //= operand[i + 1]
        elif op == '**':
            result **= operand[i + 1]
        else:
            raise ValueError(f"Invalid operator: {op}")

    return result

